{
  "technical_and_design_decisions": [
    "Create a single new Go module repository (working name fabric-lib-go) to host all externalized non-protobuf code; publish protobuf-generated code, including the gossip protos required by U1, via the existing fabric-protos-go module; tag releases with semantic versioning starting at v1.0.0.",
    "Use Hyperledger Fabric release-2.x sources with Go modules (Go >= 1.14) as the extraction baseline.",
    "Apply a copy-and-clean extraction approach: move the code into the new module, break dependencies on peer/orderer-internal packages, and never import fabric core from the new module (avoiding circular dependencies); introduce minimal local interfaces where decoupling requires it.",
    "After extraction, update fabric core to depend on the new module(s) and delete the in-tree duplicates so there is a single source of truth rather than diverging copies.",
    "Preserve API compatibility with how fabric-sdk-go currently uses the copied code where feasible; export previously internal helpers and add GoDoc; functional parity with Fabric 2.x behavior is the acceptance criterion.",
    "Implement U6 inside fabric core's golang chaincode platform: detect a go.mod file in the chaincode package and build the chaincode in module mode; mark the behavior explicitly as a deprecated, temporary workaround with a documented removal plan.",
    "Testing strategy: port the existing Fabric unit tests together with each extracted package, and add black-box parity tests that compare the externalized configtxgen/configtxlator library output (genesis blocks, config transactions, translated JSON) against output from Fabric 2.x binaries.",
    "CI setup: build, unit tests with coverage, golangci-lint, go vet, and license-header checks across a matrix of supported Go versions."
  ],
  "assumptions": [
    "All estimates are ideal work-hours for one senior Go developer experienced with Hyperledger Fabric, and include implementation, unit tests, code-review rework, and inline documentation.",
    "Community and governance tasks (repository approval, maintainers files, DCO/CLA policy) are excluded; only technical repository and CI setup is estimated.",
    "The 'useful structures' in U3/U4 are scoped to client-relevant types (e.g., ChaincodeData, CCPackage, signed chaincode deployment spec handling, ledger interfaces/util types, block and rwset helpers); full peer internals such as block storage, state database, and the gossip engine are out of scope.",
    "Migration of fabric-sdk-go to consume the externalized modules is included as end-to-end validation of the increment; any broader SDK feature work is excluded.",
    "There are no performance requirements and no backward-compatibility shims beyond functional parity with Fabric 2.x.",
    "Later removal of the U6 temporary workaround is out of scope; only its implementation, deprecation notice, and documentation are included.",
    "Existing Fabric unit tests are largely portable; rewriting tests that are tightly coupled to peer internals is included in the per-package estimates.",
    "Delivery means tagging v1.0.0 of the new module(s) and publishing usage documentation; ongoing maintenance after release is excluded."
  ],
  "activities": [
    {
      "activity_id": "A-01",
      "activity_name": "Requirements analysis and shared-library API design",
      "activity_description": "Analyze the SDK's current internal copies, define the target package layout, dependency boundaries, exported API surface, and versioning policy for the externalized modules.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-02",
      "activity_name": "Repository scaffolding and CI setup",
      "activity_description": "Create the new Go module repository structure, go.mod files, README/contribution docs, and the CI pipeline (build, test, coverage, lint, vet, license checks).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-03",
      "activity_name": "Externalize common utilities (U5)",
      "activity_description": "Extract and refactor the common and core utility packages (logging, viperutil, crypto and misc helpers) into the new module, removing peer-internal dependencies and porting unit tests.",
      "most_likely_effort": 80
    },
    {
      "activity_id": "A-04",
      "activity_name": "Externalize cauthdsl utilities (U2)",
      "activity_description": "Extract the cauthdsl policy DSL compilation/evaluation utilities, decouple from fabric-internal packages, export needed helpers, and port unit tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A-05",
      "activity_name": "Externalize ccprovider structures (U3)",
      "activity_description": "Extract client-relevant ccprovider structures (ChaincodeData, CCPackage, signed chaincode deployment spec handling) into the new module with tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A-06",
      "activity_name": "Externalize ledger structures (U4)",
      "activity_description": "Extract client-relevant ledger structures (ledger interfaces/util types, block and rwset helpers) into the new module, decoupling from peer storage internals, with tests.",
      "most_likely_effort": 64
    },
    {
      "activity_id": "A-07",
      "activity_name": "Externalize gossip protoext utilities (U1)",
      "activity_description": "Move gossip protobuf definitions to fabric-protos-go, regenerate code, and externalize the protoext helper utilities used by the discovery client, with tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A-08",
      "activity_name": "Externalize configtxgen functions (U7)",
      "activity_description": "Refactor configtxgen genesis block and configuration transaction generation into a reusable library API with clean inputs/outputs, decoupled from CLI internals, plus ported unit tests.",
      "most_likely_effort": 64
    },
    {
      "activity_id": "A-09",
      "activity_name": "Externalize configtxlator functions (U8)",
      "activity_description": "Extract configtxlator/protolator JSON-to-protobuf translation functions into a reusable library API, decoupled from REST server internals, plus ported unit tests.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "A-10",
      "activity_name": "Honor go.mod in chaincode packages (U6)",
      "activity_description": "Modify fabric core's golang chaincode platform to detect and honor go.mod files contained in a chaincode package during build, add tests, and document the feature as a deprecated temporary workaround.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A-11",
      "activity_name": "Cross-module integration and parity testing",
      "activity_description": "Add integration tests exercising the externalized packages together and black-box parity tests comparing configtxgen/configtxlator library output against Fabric 2.x binaries.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A-12",
      "activity_name": "Migrate fabric core to consume externalized modules",
      "activity_description": "Update fabric core imports and go.mod to depend on the new module(s), delete in-tree duplicate code, fix build fallout, and run fabric core unit and smoke tests.",
      "most_likely_effort": 80
    },
    {
      "activity_id": "A-13",
      "activity_name": "Migrate fabric-sdk-go to consume externalized modules",
      "activity_description": "Remove the SDK's internal/third_party copies, switch imports to the externalized modules, adapt to the cleaned APIs, and run the SDK unit and integration test suites.",
      "most_likely_effort": 64
    },
    {
      "activity_id": "A-14",
      "activity_name": "Documentation, GoDoc, and release tagging",
      "activity_description": "Write usage examples and migration notes, complete GoDoc coverage, and tag v1.0.0 releases of the new module(s).",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 648
  }
}

